    {id:'commercial-fishing',title:'Commercial fishing licence',icon:'fish',sector:'Fisheries',summary:'Prepare commercial fishing vessel, operator and activity details for a licence enquiry.',audience:'Commercial operators',eligibility:['Fishing businesses and operators intending to undertake commercial activity.','Operators who can provide vessel and responsible-party information.'],required:['Applicant and operator details','Vessel name, identification and registration details','Target fishery, gear and intended areas','Safety and compliance documentation where applicable'],process:['Review the applicable fishery requirements and operating conditions.','Identify the vessel, fishing method and target species.','Prepare the draft and supporting evidence.','Confirm official licence, quota and reporting requirements before activity begins.'],consideration:'A licence does not in itself guarantee access to a quota, area or restricted fishery.',related:['commercial-fishing.html','fisheries-rules.html','catch-reporting.html']},
    {id:'recreational-fishing',title:'Recreational fishing permit enquiry',icon:'anchor',sector:'Fisheries',summary:'Find out whether your intended recreational fishing activity requires a permit.',audience:'Recreational fishers',eligibility:['Individuals planning recreational fishing activities.','Groups organising events that may have additional requirements.'],required:['Applicant contact details','Activity location and dates','Proposed method and target species','Group or event details, if applicable'],process:['Read the current rules for your location and species.','Check whether a special authorisation is needed.','Prepare a draft enquiry if necessary.','Confirm limits and closures immediately before fishing.'],consideration:'Ordinary recreational activities may not require a permit; always check current official rules.',related:['recreational-fishing.html','fisheries-rules.html','marine-conservation.html']},
    {id:'aquaculture',title:'Aquaculture development permit',icon:'waves',sector:'Fisheries',summary:'Prepare a proposal for a marine or freshwater aquaculture operation.',audience:'Aquaculture producers',eligibility:['Individuals and entities proposing an aquaculture development.','Applicants able to demonstrate site access or permission to use the area.'],required:['Proposed site map and lease or access information','Species and farming methods','Environmental and biosecurity management plan','Infrastructure and operational description'],process:['Discuss the proposed site and activity with the ministry.','Assess environmental, navigation and biosecurity constraints.','Prepare a proposal and supporting plans.','Follow the official review and approval process.'],consideration:'Several regulatory approvals may apply to an aquaculture site.',related:['aquaculture.html','marine-conservation.html','biosecurity.html']},
    {id:'forestry',title:'Forestry activity permit',icon:'trees',sector:'Natural Resources',summary:'Prepare details for proposed forestry harvesting, planting or related land use.',audience:'Forest owners and forestry operators',eligibility:['Landholders and authorised forestry operators.','Applicants with sufficient rights to undertake work on the property.'],required:['Land parcel and ownership or access details','Maps and description of the work','Erosion, habitat and waterway protection measures','Equipment and operational timeframe'],process:['Determine whether the proposed work requires approval.','Document the affected area and ecological sensitivities.','Prepare an operational and restoration plan.','Confirm the official permissions before work starts.'],consideration:'Additional controls may apply near waterways, public land and protected habitats.',related:['forestry.html','biodiversity.html','water-resources.html']},
    {id:'water-use',title:'Water extraction or use permit',icon:'droplets',sector:'Natural Resources',summary:'Prepare an enquiry about taking, diverting or using water.',audience:'Farmers, businesses and landholders',eligibility:['People or businesses proposing to take or divert water.','Applicants with site access and a defined intended use.'],required:['Water source and extraction location','Estimated volume, purpose and schedule','Site plan and property information','Impact mitigation or monitoring plan where relevant'],process:['Identify the proposed source, use and seasonal demand.','Check any restrictions and environmental requirements.','Prepare supporting flow, storage or irrigation information.','Seek official approval before any activity that requires consent.'],consideration:'Availability and environmental flow protections may affect whether use can be authorised.',related:['water-resources.html','soil-water.html','public-land.html']},
    {id:'mining',title:'Mineral exploration or extraction permit',icon:'mountain',sector:'Natural Resources',summary:'Prepare an initial proposal for mineral exploration or extraction.',audience:'Exploration and extraction applicants',eligibility:['Individuals and businesses with a defined exploration or extraction proposal.','Applicants able to provide land and environmental information.'],required:['Applicant and company details','Area or coordinates of the proposed activity','Mineral type and methods','Environmental, rehabilitation and safety approach'],process:['Identify the type and scale of proposed activity.','Review land access and sensitive areas.','Prepare technical and environmental documentation.','Confirm which consents, bonds and reporting duties apply.'],consideration:'Exploration, extraction and access permissions are separate matters and may each need approval.',related:['mining.html','public-land.html','biodiversity.html']},
    {id:'land-access',title:'Public land access or activity permit',icon:'map',sector:'Natural Resources',summary:'Prepare an enquiry for organised activity, access or temporary use of public land.',audience:'Community groups, visitors and businesses',eligibility:['Organisers proposing activities on public land.','People needing permission for restricted access or commercial use.'],required:['Proposed location and map','Purpose, duration and approximate attendance','Risk and environmental protection plan','Proof of relevant insurance where applicable'],process:['Check whether the land is publicly accessible for the intended activity.','Identify protected features and other land users.','Prepare your activity details and supporting information.','Obtain any necessary permission before undertaking restricted activities.'],consideration:'Public access is subject to local restrictions, safety conditions and conservation rules.',related:['public-land.html','biodiversity.html','forestry.html']}
